    ) as v(id, prompt_md5, passage_md5, options_md5, correct_index, explain_md5)
  loop
    if exists (select 1 from public.questions q where q.id = fix.id) then
      present := present + 1;
    end if;
    if exists (
      select 1 from public.questions q
       where q.id = fix.id
         and q.status = 'draft'
         and q.verification = 'agreed'
         and md5(q.prompt) = fix.prompt_md5
         and md5(q.passage) is not distinct from fix.passage_md5
         and md5(q.options::text) = fix.options_md5
         and q.correct_index = fix.correct_index
         and md5(q.explain) = fix.explain_md5
    ) then
      ok := ok || fix.id;
    elsif exists (select 1 from public.questions q where q.id = fix.id and q.status <> 'published') then
      skipped := skipped || fix.id;
    end if;
  end loop;

  if present = 0 then
    raise notice '0022: de nya frågorna finns inte i databasen; inget görs.';
    return;
  end if;

  update public.questions set status = 'published' where id = any(ok);

  update public.questions
     set status = 'rejected'
   where id in ('ord-21', 'mek-1', 'mek-2', 'mek-3', 'mek-4', 'mek-5', 'mek-6', 'mek-7', 'mek-8', 'mek-9', 'mek-10', 'mek-11', 'mek-12', 'mek-13', 'mek-14', 'mek-15', 'mek-16', 'mek-17', 'mek-18', 'mek-19', 'mek-20', 'mek-21', 'mek-22', 'mek-23', 'mek-24', 'mek-25', 'mek-26', 'mek-27', 'mek-28', 'mek-29', 'mek-30', 'mek-31', 'mek-32', 'mek-33', 'mek-34', 'mek-35', 'mek-36', 'mek-37', 'mek-38', 'mek-39', 'mek-40', 'mek-41', 'mek-42', 'mek-43', 'mek-44', 'mek-45', 'mek-46', 'mek-47', 'mek-48', 'mek-49', 'mek-50', 'mek-51', 'mek-52', 'mek-53', 'mek-54', 'mek-55', 'mek-56', 'mek-57', 'mek-58', 'mek-59', 'mek-60', 'mek-61', 'mek-62', 'mek-63', 'mek-64', 'mek-65', 'mek-66', 'mek-67', 'mek-68', 'mek-69', 'mek-70', 'mek-71', 'mek-72', 'mek-73', 'mek-74', 'mek-75', 'mek-76', 'mek-77', 'mek-78', 'mek-79', 'mek-80', 'las-1', 'las-2', 'las-3', 'las-4', 'las-5', 'las-6', 'elf-1', 'elf-2', 'elf-3', 'elf-4', 'dtk-2', 'dtk-3', 'dtk-4', 'dtk-5', 'dtk-6', 'dtk-7', 'dtk-8', 'xyz-1', 'xyz-2', 'xyz-3', 'xyz-4', 'xyz-5', 'xyz-6', 'xyz-7', 'xyz-8', 'kva-3', 'nog-1', 'nog-2', 'nog-3', 'nog-4', 'nog-5', 'nog-6', 'nog-7', 'nog-8')
     and status <> 'rejected';

  raise notice '0022: % publicerade, % hoppades över: %', coalesce(array_length(ok, 1), 0),
    coalesce(array_length(skipped, 1), 0), array_to_string(skipped, ', ');
end
